if(!is_string($generationMode)||!in_array($generationMode,['chapter','advanced'],true)||!is_string($generationKind)||!in_array($generationKind,['written','mcq','mixed'],true))denySchoolRequest('Choose a valid paper generation mode.',422);
if($_SERVER['REQUEST_METHOD']==='GET'&&isset($_GET['grid_id'])){try{$g=examGridRecord($db,$actor,learningId($_GET['grid_id']));$class=$g['local_class_id'];$subject=$g['local_subject_id'];$initialConfig=examGridInputJson($g['config_json']);$generationMode='advanced';}catch(InvalidArgumentException $e){denySchoolRequest($e->getMessage(),404);}}
if($_SERVER['REQUEST_METHOD']==='POST'){
