        if(!empty($_POST['exam_id'])){$selectedExam=schoolRecord($db,'exams',learningId($_POST['exam_id']),$actor['school_id']);$q=$db->prepare('SELECT id FROM exam_subjects WHERE exam_id=? AND class_id=? AND subject_id=?');$q->execute([$selectedExam['id'],$class,$subject]);if(!$q->fetchColumn())throw new InvalidArgumentException('Map this class subject to the selected exam first, or choose a standalone paper.');$title=$selectedExam['name'];}
        if($generationMode==='chapter')$paper=examGenerateChapterPaper($db,$actor,$class,$subject,$_POST);
        else{$initialConfig=examGridInputJson($_POST['config_json']??null);$paper=examGeneratePaper($db,$actor,$class,$subject,$initialConfig);}
        learningAudit($db,$actor,'Generate exam paper','exam_paper_grids',0);
    }catch(InvalidArgumentException $e){http_response_code(422);$error=$e->getMessage();}catch(Throwable $e){http_response_code(500);$error=schoolPublicError($e);}
}
[$classes,$subjectsByClass]=examPageSelectors($db,$actor);try{[$chapters,$topicsByChapter,$savedGrids,$referenceGrids]=examPageCatalog($db,$actor,$class,$subject);}catch(InvalidArgumentException $e){denySchoolRequest($e->getMessage(),404);}
$q=$db->prepare('SELECT * FROM schools WHERE id=?');$q->execute([$actor['school_id']]);$school=$q->fetch(PDO::FETCH_ASSOC)?:[];
$q=$db->prepare('SELECT id,name FROM exams WHERE school_id=? ORDER BY id DESC');$q->execute([$actor['school_id']]);$exams=$q->fetchAll(PDO::FETCH_ASSOC);
